package com.acaivis.controller; import com.acaivis.dto.*; import com.acaivis.model.OrderStatus; import com.acaivis.service.OrderService; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/orders") public class OrderController {private final OrderService s;public OrderController(OrderService s){this.s=s;} @PostMapping @ResponseStatus(HttpStatus.CREATED) public OrderResponse create(@Valid @RequestBody OrderRequest d){return s.create(d);} @GetMapping("/tracking/{code}") public TrackingOrderResponse tracking(@PathVariable String code){return s.tracking(code);} @GetMapping("/{id}") public OrderResponse one(@PathVariable Long id){return s.find(id);} @GetMapping("/{id}/history") public List<OrderStatusHistoryResponse> history(@PathVariable Long id){return s.statusHistory(id);} @GetMapping("/{id}/customer-history") public List<OrderResponse> customerHistory(@PathVariable Long id){return s.customerHistory(id);} @GetMapping public List<OrderResponse> all(){return s.all();} @PatchMapping("/{id}/status") public OrderResponse status(@PathVariable Long id,@RequestParam OrderStatus status){return s.updateStatus(id,status);}}
